import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.BC3NdntU.js";const c=JSON.parse('{"title":"11.10 落地工程:评估 / 监控 / 成本 / 安全","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.10-落地工程评估监控成本安全.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.10-落地工程评估监控成本安全.md","lastUpdated":1788952151000}'),o={name:"卷十一-AIAgentHarness与提示词工程/11.10-落地工程评估监控成本安全.md"};function d(s,t,l,i,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="_11-10-落地工程-评估-监控-成本-安全" tabindex="-1">11.10 落地工程:评估 / 监控 / 成本 / 安全 <a class="header-anchor" href="#_11-10-落地工程-评估-监控-成本-安全" aria-label="Permalink to &quot;11.10 落地工程:评估 / 监控 / 成本 / 安全&quot;">​</a></h1><h2 id="引言-从-能跑-到-敢上线-的最后一步" tabindex="-1">引言:从&quot;能跑&quot;到&quot;敢上线&quot;的最后一步 <a class="header-anchor" href="#引言-从-能跑-到-敢上线-的最后一步" aria-label="Permalink to &quot;引言:从&quot;能跑&quot;到&quot;敢上线&quot;的最后一步&quot;">​</a></h2><p>Demo 能跑 ≠ 生产能用。企业 AI 落地 90% 卡在工程化:不会评估、不敢监控、成本失控、安全没底。这一章把&quot;上线前必须想清楚的四个问题&quot;讲透。</p><hr><h2 id="一、评估-eval-怎么知道-agent-干得好不好" tabindex="-1">一、评估(Eval):怎么知道 Agent 干得好不好 <a class="header-anchor" href="#一、评估-eval-怎么知道-agent-干得好不好" aria-label="Permalink to &quot;一、评估(Eval):怎么知道 Agent 干得好不好&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>做法</th><th>适用</th></tr></thead><tbody><tr><td><strong>人工评估</strong></td><td>抽样本人工打分(准确/相关/有用)</td><td>上线前小规模</td></tr><tr><td><strong>LLM-as-judge</strong></td><td>用更强的模型给回答打分</td><td>规模化自动评估</td></tr><tr><td><strong>基准集</strong></td><td>预置&quot;问题 → 期望答案 → 应命中文档&quot;</td><td>回归测试、持续监控</td></tr><tr><td><strong>检索评测</strong></td><td>Recall@k / MRR</td><td>单独评估检索质量</td></tr></tbody></table><blockquote><p><strong>铁律:没有 eval 就别上线。</strong> 至少要有&quot;一撮带标准答案的问题集&quot;,每次改 prompt/模型/分块都能跑一遍,防止&quot;越改越差&quot;。</p></blockquote><hr><h2 id="二、监控-上线后的眼睛" tabindex="-1">二、监控(上线后的眼睛) <a class="header-anchor" href="#二、监控-上线后的眼睛" aria-label="Permalink to &quot;二、监控(上线后的眼睛)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>告警</th></tr></thead><tbody><tr><td>成功率</td><td>完成任务/总请求</td><td>突降</td></tr><tr><td>延迟</td><td>P50/P95 响应时间</td><td>突增</td></tr><tr><td>token 用量</td><td>单次对话 token 数</td><td>失控</td></tr><tr><td>成本</td><td>每请求/每用户成本</td><td>超预算</td></tr><tr><td>用户反馈</td><td>👍/👎、重试率</td><td>差评上升</td></tr></tbody></table><blockquote><p>至少监控&quot;成功率 + 延迟 + 成本&quot;三项,配合日志追踪(11.3 的观测)。</p></blockquote><hr><h2 id="三、成本控制-呼应-11-3" tabindex="-1">三、成本控制(呼应 11.3) <a class="header-anchor" href="#三、成本控制-呼应-11-3" aria-label="Permalink to &quot;三、成本控制(呼应 11.3)&quot;">​</a></h2><ol><li><strong>模型分级</strong>:简单步骤用便宜小模型,难步骤才上大模型</li><li><strong>上下文裁剪</strong>:压缩历史、只保留决策结论(11.4)</li><li><strong>缓存</strong>:相同/相似请求命中缓存,不重复调 LLM</li><li><strong>步数上限</strong>:防无限循环烧钱(11.2)</li></ol><hr><h2 id="四、安全加固-呼应-11-5" tabindex="-1">四、安全加固(呼应 11.5) <a class="header-anchor" href="#四、安全加固-呼应-11-5" aria-label="Permalink to &quot;四、安全加固(呼应 11.5)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>防护</th></tr></thead><tbody><tr><td>提示注入</td><td>工具只信校验后的参数与白名单;不执行模型输出的自由指令</td></tr><tr><td>数据泄露</td><td>敏感数据不喂模型 / 脱敏;权限最小化</td></tr><tr><td>越权操作</td><td>高风险动作(删/发/支付)人工确认</td></tr><tr><td>沙箱</td><td>代码执行、文件操作隔离运行</td></tr></tbody></table><hr><h2 id="五、落地路线图-一句话概括" tabindex="-1">五、落地路线图(一句话概括) <a class="header-anchor" href="#五、落地路线图-一句话概括" aria-label="Permalink to &quot;五、落地路线图(一句话概括)&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先选场景(知识库问答/客服/代码) → 搭最小闭环 → 建 eval 基准集</span></span>
<span class="line"><span>→ 上线灰度 + 监控 → 按数据迭代(改 prompt/分块/模型) → 逐步放量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>核心心法:<strong>先跑通再优化,先评估再上线,先监控再放量。</strong></p></blockquote><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>落地四问:评估(eval 基准集 + LLM-as-judge)/ 监控(成功率·延迟·成本)/ 成本(分级·缓存·裁剪)/ 安全(防注入·脱敏·人审)</span></span>
<span class="line"><span>路线:选场景 → 最小闭环 → eval → 灰度监控 → 迭代放量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="七、面试-实践要点" tabindex="-1">七、面试/实践要点 <a class="header-anchor" href="#七、面试-实践要点" aria-label="Permalink to &quot;七、面试/实践要点&quot;">​</a></h2><p><strong>Q1:为什么说&quot;没有 eval 就别上线&quot;?</strong></p><p>LLM 是非确定性的,改 prompt/模型/分块都可能让质量悄悄变差。没有 eval 基准集,你无法发现&quot;越改越差&quot;,也无法回滚。eval 是&quot;可观测的质量&quot;。</p><p><strong>Q2:LLM-as-judge 是什么?可靠吗?</strong></p><p>用一个(通常更强的)模型当&quot;裁判&quot;,给回答打分(准确/相关/是否有幻觉)。优点是能规模化自动评估;缺点是裁判本身也可能有偏见,需与人工评估交叉验证。</p><p><strong>Q3:生产 Agent 的成本主要花在哪?怎么控?</strong></p><p>大头在<strong>每轮对话的 token 消耗</strong>(尤其长上下文)。控法:模型分级(小模型干粗活)、上下文裁剪(压缩历史)、缓存命中、步数上限——四管齐下,成本能降一个数量级。</p><hr><p>📎 参考:<a href="https://www.anthropic.com/" target="_blank" rel="noreferrer">Anthropic</a>/OpenAI 生产实践文档、LangSmith/Langfuse(评估与追踪)、掘金《企业级 AI Agent 落地指南》</p>`,34)])])}const b=a(o,[["render",d]]);export{c as __pageData,b as default};
